static void handle_data(ctx, rank, psn_wire, payload) {
   uint32_t p = (psn_wire - start) & MASK24;
   // required source check happens in endpoint validity
   if (p >= K) { ep_bad++; return; }   // endpoint-invalid
   rx_data++;  // accepted-endpoint DATA
   if (p >= b + N) { blocked++; }
   else if (p < b) { stale++; repeat[rank]=1; }
   else {
      idx = p % N; slot = &slots[idx];
      if (slot->in_use && slot->psn == p && (slot->mask & (1<<rank))) { dups++; repeat[rank]=1; }
      else {
         if (!slot->in_use || slot->psn != p) {
            if (slot->in_use && slot->psn != p) overwrites++;  // must never happen
