static void service(ctx_t *c, int retry_rank) {
    advance_E(c);
    if (retry_rank >= 0) c->repeat[retry_rank] = 1;
    for (int r=0;r<4;r++) {
        if (c->E[r] > 0 && (c->E[r] > c->U[r] || c->repeat[r])) {
            if (!emit_ack(c, r, (uint32_t)c->E[r])) goto done;
            c->U[r] = c->E[r];
            c->repeat[r] = 0;
        }
    }
    if (retry_rank >= 0) {
        uint64_t q = c->down[retry_rank];
        while (q < c->sent[retry_rank]) {
            if (!emit_result(c, retry_rank, q)) goto done;
            q++;
