def parse_result(blob):
    off = 0
    state = list(struct.unpack_from('<32Q', blob, off)); off += 256
    digest = struct.unpack_from('<Q', blob, off)[0]; off += 8
    sha = blob[off:off+32].hex(); off += 32
    packets, bytes_ = struct.unpack_from('<QQ', blob, off); off += 16
    (trace_n,) = struct.unpack_from('<I', blob, off); off += 4
    trace = []
    for _ in range(trace_n):
        rank = blob[off]; off += 1
        (flen,) = struct.unpack_from('<I', blob, off); off += 4
        trace.append({'rank': rank, 'hex': blob[off:off+flen].hex()}); off += flen
    (snap_n,) = struct.unpack_from('<I', blob, off); off += 4
    snaps = []
    for _ in range(snap_n):
        st = list(struct.unpack_from('<32Q', blob, off)); off += 256
        dg = struct.unpack_from('<Q', blob, off)[0]; off += 8
        sh = blob[off:off+32].hex(); off += 32
        pk, by = struct.unpack_from('<QQ', blob, off); off += 16
        (tl,) = struct.unpack_from('<H', blob, off); off += 2
        tag = blob[off:off+tl].decode('utf-8'); off += tl
        snaps.append({'tag': tag, 'state': st, 'buffer': format(dg,'016x'), 'wire_sha256': sh, 'packets': pk, 'bytes': by})
    return {'state': state, 'buffer': format(digest,'016x'), 'wire_sha256': sha, 'packets': packets, 'bytes': bytes_, 'snapshots': snaps, 'trace': trace}
```

