    sw[5] = (uint8_t)(rank + 1);
}

static uint32_t host_ip_of(int rank) { return htonl(0x0a000001u + (uint32_t)rank); }
static uint32_t switch_ip_of(int rank) { return htonl(0x0a000065u + (uint32_t)rank); }
static uint32_t host_qpn_of(int rank) { return 0x100u + (uint32_t)rank; }
static uint32_t switch_qpn_of(int rank) { return 0x200u + (uint32_t)rank; }

static int rank_from_ordinal_excluding(int excluded, int ordinal) {
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == excluded) continue;
        if (ordinal == 0) return r;
        ordinal--;
    }
    return 0;
}

static int ordinal_excluding(int excluded, int rank) {
    int ordinal = 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == excluded) continue;
        if (r == rank) return ordinal;
        ordinal++;
    }
    return 0;
}

static int is_required_source(const ctx_t *c, int rank) {
    if (c->prim == P_BCAST) return rank == c->root;
    return 1;
}

static uint8_t *slot_payload(const ctx_t *c, uint64_t p) {
    return c->pool + (size_t)(p % c->N) * (size_t)c->slot_bytes;
}

static uint32_t *slot_words(const ctx_t *c, uint64_t p) {
    return (uint32_t *)slot_payload(c, p);
}

static uint16_t rd16(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

static uint32_t rd32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static uint32_t rd32le(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static int ip_checksum_ok(const uint8_t *hdr) {
    uint32_t sum = 0;
    for (int i = 0; i < 10; i++) sum += rd16(hdr + 2 * i);
    while (sum >> 16) sum = (sum & 0xffffu) + (sum >> 16);
    return (sum & 0xffffu) == 0xffffu;
}

/* ------------------------------------------------------------------ */
/* strict wire acceptance                                             */
/* ------------------------------------------------------------------ */

typedef struct {
    int is_ack;
    uint32_t psn;
    uint32_t qpn;
    const uint8_t *payload;
    uint32_t plen;
} frame_t;

static int wire_valid(const uint8_t *f, size_t len, frame_t *out) {
    const size_t head = sizeof(epic_eth_t) + sizeof(epic_ipv4_t) +
                        sizeof(epic_udp_t) + sizeof(epic_bth_t) + 4u;
    if (!f || len < head) return 0;
    if (rd16(f + 12) != 0x0800u) return 0;              /* Ethernet IPv4 */
    const uint8_t *ip = f + sizeof(epic_eth_t);
    if (ip[0] != 0x45) return 0;                        /* version/IHL */
    uint32_t iplen = rd16(ip + 2);
    if ((size_t)iplen + sizeof(epic_eth_t) != len) return 0;
    if (ip[9] != 17) return 0;                          /* protocol UDP */
    uint16_t frag = rd16(ip + 6);
    if (frag != 0x0000u && frag != 0x4000u) return 0;   /* DF only */
    if (!ip_checksum_ok(ip)) return 0;
    const uint8_t *udp = ip + sizeof(epic_ipv4_t);
    uint32_t udplen = rd16(udp + 4);
    if (udplen + sizeof(epic_ipv4_t) != iplen) return 0;
    if (udplen < sizeof(epic_udp_t) + sizeof(epic_bth_t) + 4u) return 0;
    if (rd16(udp) != UDP_PORT_ROCE) return 0;
    if (rd16(udp + 2) != UDP_PORT_ROCE) return 0;
    if (rd16(udp + 6) != 0) return 0;                   /* UDP checksum zero */
    const uint8_t *bth = udp + sizeof(epic_udp_t);
    uint8_t opcode = bth[0];
    if (opcode != 0x04 && opcode != 0x11) return 0;
    if (bth[1] != 0) return 0;                          /* flags/padding */
    if (rd16(bth + 2) != 0xffffu) return 0;             /* pkey */
    uint32_t qpn = rd32(bth + 4);
    if (qpn & 0xff000000u) return 0;                    /* QPN top byte */
    uint32_t apsn = rd32(bth + 8);
    uint8_t top = (uint8_t)(apsn >> 24);
    if (opcode == 0x04 ? (top != 0x80u) : (top != 0x00u)) return 0;
    uint32_t bodylen = udplen - (uint32_t)sizeof(epic_udp_t) -
                       (uint32_t)sizeof(epic_bth_t) - 4u;
    memset(out, 0, sizeof *out);
    out->psn = apsn & MASK24;
    out->qpn = qpn;
    if (opcode == 0x11) {
        if (bodylen != 4u) return 0;
        const uint8_t *aeth = bth + sizeof(epic_bth_t);
        if (aeth[0] != 0x1fu) return 0;
        uint32_t low = ((uint32_t)aeth[1] << 16) | ((uint32_t)aeth[2] << 8) |
                       (uint32_t)aeth[3];
        if (low != ((out->psn + 1u) & MASK24)) return 0;
        out->is_ack = 1;
    } else {
        out->is_ack = 0;
        out->payload = bth + sizeof(epic_bth_t);
        out->plen = bodylen;
    }
    uint32_t stored = rd32le(f + len - 4);
    if (epic_compute_icrc(f, len) != stored) return 0;
    return 1;
}

static int endpoint_valid(const ctx_t *c, int rank, const uint8_t *f,
                          const frame_t *fr) {
    uint8_t hm[6], sm[6];
    (void)c;
    port_macs(rank, hm, sm);
    if (memcmp(f, sm, 6) != 0) return 0;      /* destination = switch */
    if (memcmp(f + 6, hm, 6) != 0) return 0;  /* source = host */
    const uint8_t *ip = f + sizeof(epic_eth_t);
    const uint8_t *hi = (const uint8_t *)&(uint32_t){ host_ip_of(rank) };
    const uint8_t *si = (const uint8_t *)&(uint32_t){ switch_ip_of(rank) };
    if (memcmp(ip + 12, hi, 4) != 0) return 0;
    if (memcmp(ip + 16, si, 4) != 0) return 0;
    if (fr->qpn != switch_qpn_of(rank)) return 0;
    return 1;
}

/* ------------------------------------------------------------------ */
/* egress                                                             */
/* ------------------------------------------------------------------ */

static int transmit(ctx_t *c, int rank, const uint8_t *frame, size_t len,
                    int is_ack) {
    if (c->budget == 0) {
        c->failed++;
        return 0;
    }
    if (c->budget > 0) c->budget--;
    uint8_t prefix[5];
    prefix[0] = (uint8_t)rank;
    prefix[1] = (uint8_t)(len & 0xffu);
    prefix[2] = (uint8_t)((len >> 8) & 0xffu);
    prefix[3] = (uint8_t)((len >> 16) & 0xffu);
    prefix[4] = (uint8_t)((len >> 24) & 0xffu);
    sha_update(&c->sha, prefix, sizeof prefix);
    sha_update(&c->sha, frame, len);
    c->packets++;
    c->bytes += len;
    if (is_ack) c->tx_ack++; else c->tx_data++;
    if (c->trace_n < c->trace_limit && c->trace_n < MAX_TRACE) {
        c->trace_rank[c->trace_n] = rank;
        c->trace_len[c->trace_n] = (uint32_t)len;
        memcpy(c->trace_frame[c->trace_n], frame, len);
        c->trace_n++;
    }
    return 1;
}

static int emit_ack(ctx_t *c, int rank, uint64_t prefix_len) {
    uint8_t hm[6], sm[6];
    uint32_t psn = (c->start + (uint32_t)((prefix_len - 1u) & MASK24)) & MASK24;
    port_macs(rank, hm, sm);
    size_t len = epic_build_roce_ack(c->fbuf, sizeof c->fbuf, sm, hm,
                                     switch_ip_of(rank), host_ip_of(rank),
                                     UDP_PORT_ROCE, UDP_PORT_ROCE,
                                     host_qpn_of(rank), psn);
    if (!len) return 0;
    return transmit(c, rank, c->fbuf, len, 1);
}

static int emit_data(ctx_t *c, int rank, uint64_t q, const uint8_t *raw,
                     const uint32_t *words) {
    uint8_t hm[6], sm[6];
    uint32_t psn = (uint32_t)((c->start + q) & MASK24);
    port_macs(rank, hm, sm);
    size_t len;
    if (raw) {
        len = epic_build_roce_data_raw(c->fbuf, sizeof c->fbuf, sm, hm,
                                       switch_ip_of(rank), host_ip_of(rank),
                                       UDP_PORT_ROCE, UDP_PORT_ROCE,
                                       host_qpn_of(rank), psn, raw, c->pbytes);
    } else {
        len = epic_build_roce_data(c->fbuf, sizeof c->fbuf, sm, hm,
                                   switch_ip_of(rank), host_ip_of(rank),
                                   UDP_PORT_ROCE, UDP_PORT_ROCE,
                                   host_qpn_of(rank), psn,
                                   (const int32_t *)words, c->pbytes);
    }
    if (!len) return 0;
    return transmit(c, rank, c->fbuf, len, 0);
}

/* ------------------------------------------------------------------ */
/* output space mapping                                               */
/* ------------------------------------------------------------------ */

static uint64_t record_input(const ctx_t *c, int dest, uint64_t q) {
    switch (c->prim) {
    case P_ALLGATHER:
        return q / 3u;
    case P_RSCATTER:
        return (uint64_t)dest * c->B + q;
    case P_BARRIER:
        return 0;
    default:
        return q;
    }
}

static int record_ready(const ctx_t *c, int dest, uint64_t q) {
    uint64_t p = record_input(c, dest, q);
    if (p >= c->K) return 0;
    const slot_t *s = &c->slots[p % c->N];
    return s->in_use && s->psn == p && s->complete;
}

static int emit_record(ctx_t *c, int dest, uint64_t q) {
    uint64_t p = record_input(c, dest, q);
    if (c->prim == P_BARRIER) return emit_data(c, dest, q, NULL, NULL);
    if (c->prim == P_ALLGATHER) {
        int ordinal = (int)(q % 3u);
        int src = rank_from_ordinal_excluding(dest, ordinal);
        return emit_data(c, dest, q, slot_payload(c, p) + (size_t)src * c->pbytes,
                         NULL);
    }
    if (c->prim == P_BCAST) return emit_data(c, dest, q, slot_payload(c, p), NULL);
    return emit_data(c, dest, q, NULL, slot_words(c, p));
}

/* ------------------------------------------------------------------ */
/* sequence prefixes                                                  */
/* ------------------------------------------------------------------ */

static void advance_received(ctx_t *c, int rank) {
    uint32_t bit = 1u << rank;
    while (c->R[rank] < c->K) {
        uint64_t p = c->R[rank];
        if (p < c->b) {
            c->R[rank] = c->b;
            continue;
        }
        const slot_t *s = &c->slots[p % c->N];
        if (s->in_use && s->psn == p && (s->mask & bit)) c->R[rank]++;
        else break;
    }
}

static int contribution_safe(const ctx_t *c, int rank, uint64_t p) {
    switch (c->prim) {
    case P_ALLREDUCE:
        return c->down[rank] > p;
    case P_BARRIER:
        return c->down[rank] >= 1;
    case P_REDUCE:
        return c->down[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (d == c->root) continue;
            if (c->down[d] <= p) return 0;
        }
        return 1;
    case P_RSCATTER: {
        uint32_t d = (uint32_t)(p / c->B);
        return c->down[d] > (p % c->B);
    }
    case P_ALLGATHER:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (d == rank) continue;
            int ordinal = ordinal_excluding(d, rank);
            if (c->down[d] < 3u * p + (uint64_t)ordinal + 1u) return 0;
        }
        return 1;
    default:
        return 0;
    }
}

static void advance_eligible(ctx_t *c) {
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (c->mode == 3) {
            c->E[r] = c->R[r];
            continue;
        }
        while (c->E[r] < c->R[r] && contribution_safe(c, r, c->E[r])) c->E[r]++;
    }
}

static int outputs_acknowledged(const ctx_t *c, uint64_t p) {
    switch (c->prim) {
    case P_ALLREDUCE:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++)
            if (c->down[d] <= p) return 0;
        return 1;
    case P_REDUCE:
        return c->down[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (d == c->root) continue;
            if (c->down[d] <= p) return 0;
        }
        return 1;
    case P_BARRIER:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++)
            if (c->down[d] < 1) return 0;
        return 1;
    case P_ALLGATHER:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++)
            if (c->down[d] < 3u * p + 3u) return 0;
        return 1;
    case P_RSCATTER: {
        uint32_t d = (uint32_t)(p / c->B);
        return c->down[d] > (p % c->B);
    }
    default:
        return 0;
    }
}

static int retireable(const ctx_t *c, uint64_t p) {
    const slot_t *s = &c->slots[p % c->N];
    if (!s->in_use || s->psn != p || !s->complete) return 0;
    if (!outputs_acknowledged(c, p)) return 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (!is_required_source(c, r)) continue;
        if (c->U[r] <= p) return 0;
    }
    return 1;
}

static void retire(ctx_t *c) {
    while (c->b < c->K && retireable(c, c->b)) {
        slot_t *s = &c->slots[c->b % c->N];
        s->in_use = 0;
        s->mask = 0;
        s->complete = 0;
        s->psn = 0;
        c->occupied--;
        c->b++;
    }
}

/* ------------------------------------------------------------------ */
/* service opportunity                                                */
/* ------------------------------------------------------------------ */

static void service(ctx_t *c, int retry_rank) {
    advance_eligible(c);
    if (retry_rank >= 0) c->repeat[retry_rank] = 1;

    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (c->E[r] == 0) continue;
        if (c->E[r] <= c->U[r] && !c->repeat[r]) continue;
        if (!emit_ack(c, r, c->E[r])) goto done;
        c->U[r] = c->E[r];
        c->repeat[r] = 0;
    }

    if (retry_rank >= 0) {
        uint64_t q = c->down[retry_rank];
        while (q < c->sent[retry_rank]) {
            if (!emit_record(c, retry_rank, q)) goto done;
            q++;
        }
    }

    for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
        while (c->sent[d] < c->out_total[d] && record_ready(c, d, c->sent[d])) {
            if (!emit_record(c, d, c->sent[d])) goto done;
            c->sent[d]++;
        }
    }

done:
    retire(c);
}

/* ------------------------------------------------------------------ */
/* ingress handling                                                   */
/* ------------------------------------------------------------------ */

static void store_contribution(ctx_t *c, uint64_t p, int rank,
                               const uint8_t *payload) {
    uint8_t *pay = slot_payload(c, p);
    switch (c->prim) {
    case P_ALLGATHER:
        memcpy(pay + (size_t)rank * c->pbytes, payload, c->pbytes);
        break;
    case P_BCAST:
        memcpy(pay, payload, c->pbytes);
        break;
    case P_BARRIER:
        break;
    default: {
        uint32_t *acc = (uint32_t *)pay;
        for (uint32_t j = 0; j < c->D; j++) acc[j] += rd32(payload + 4u * j);
        break;
    }
    }
}

static void handle_data(ctx_t *c, int rank, uint32_t p, const uint8_t *payload) {
    if ((uint64_t)p >= c->b + c->N) {
        c->blocked++;
        return;
    }
    if ((uint64_t)p < c->b) {
        c->stale++;
        c->repeat[rank] = 1;
        return;
    }
    slot_t *s = &c->slots[p % c->N];
    uint8_t bit = (uint8_t)(1u << rank);
    if (s->in_use && s->psn == p && (s->mask & bit)) {
        c->dups++;
        c->repeat[rank] = 1;
        return;
    }
    if (!s->in_use || s->psn != p) {
        if (s->in_use && s->psn != p) c->overwrites++;
        s->in_use = 1;
        s->psn = p;
        s->mask = 0;
        s->complete = 0;
        memset(slot_payload(c, p), 0, c->slot_bytes);
        c->occupied++;
    }
    store_contribution(c, p, rank, payload);
    s->mask |= bit;
    if (s->mask == c->required) s->complete = 1;
    c->accepted++;
    advance_received(c, rank);
}

static void handle_ack(ctx_t *c, int rank, uint32_t wire_psn) {
    uint32_t len = (wire_psn - c->start + 1u) & MASK24;
    if ((uint64_t)len > c->down[rank] && (uint64_t)len <= c->sent[rank]) {
        c->down[rank] = len;
    } else {
        c->ack_ignored++;
    }
}

static void ingress(ctx_t *c, int rank, const uint8_t *frame, size_t len) {
    frame_t fr;
    if (!wire_valid(frame, len, &fr)) {
        c->wire_bad++;
        return;
    }
    if (!fr.is_ack && fr.plen != c->pbytes) {
        c->wire_bad++;
        return;
    }
    if (!endpoint_valid(c, rank, frame, &fr)) {
        c->ep_bad++;
        return;
    }
    if (fr.is_ack) {
        c->rx_ack++;
        handle_ack(c, rank, fr.psn);
    } else {
        uint32_t p = (fr.psn - c->start) & MASK24;
        if (p >= c->K || !is_required_source(c, rank)) {
            c->ep_bad++;
            return;
        }
        c->rx_data++;
        handle_data(c, rank, p, fr.payload);
    }
    service(c, -1);
}

/* ------------------------------------------------------------------ */
/* ingress frame generation (event expansion)                         */
/* ------------------------------------------------------------------ */

static size_t build_ingress_data(ctx_t *c, int rank, uint32_t psn,
                                 const uint8_t *payload) {
    uint8_t hm[6], sm[6];
    port_macs(rank, hm, sm);
    return epic_build_roce_data_raw(c->fbuf, sizeof c->fbuf, hm, sm,
                                    host_ip_of(rank), switch_ip_of(rank),
                                    UDP_PORT_ROCE, UDP_PORT_ROCE,
                                    switch_qpn_of(rank), psn, payload,
                                    c->pbytes);
}

static size_t build_ingress_ack(ctx_t *c, int rank, uint32_t psn) {
    uint8_t hm[6], sm[6];
    port_macs(rank, hm, sm);
    return epic_build_roce_ack(c->fbuf, sizeof c->fbuf, hm, sm,
                               host_ip_of(rank), switch_ip_of(rank),
                               UDP_PORT_ROCE, UDP_PORT_ROCE,
                               switch_qpn_of(rank), psn);
}

static void fill_payload(ctx_t *c, uint32_t seed, uint64_t p, int rank) {
    for (uint32_t j = 0; j < c->D; j++) {
        uint32_t v = seed + 0x9e3779b9u * (uint32_t)(p + 1u) +
                     0x85ebca6bu * (uint32_t)(rank + 1) +
                     0xc2b2ae35u * (j + 1u);
        c->pbuf[4u * j] = (uint8_t)(v >> 24);
        c->pbuf[4u * j + 1u] = (uint8_t)(v >> 16);
        c->pbuf[4u * j + 2u] = (uint8_t)(v >> 8);
        c->pbuf[4u * j + 3u] = (uint8_t)v;
    }
}

static void inject_data(ctx_t *c, int rank, uint64_t p, const uint8_t *payload,
                        const uint8_t *xor, uint32_t nxor) {
    uint32_t psn = (uint32_t)((c->start + p) & MASK24);
    size_t len = build_ingress_data(c, rank, psn, payload);
    if (!len) return;
    for (uint32_t i = 0; i < nxor; i++) {
        uint32_t off = rd32le(xor + 5u * i);
        uint8_t val = xor[5u * i + 4u];
        if (off < len) c->fbuf[off] ^= val;
    }
    ingress(c, rank, c->fbuf, len);
}

static void inject_ack(ctx_t *c, int rank, uint64_t upto) {
    uint32_t psn = (uint32_t)((c->start + upto - 1u) & MASK24);
    size_t len = build_ingress_ack(c, rank, psn);
    if (!len) return;
    ingress(c, rank, c->fbuf, len);
}

/* ------------------------------------------------------------------ */
/* certificates                                                       */
/* ------------------------------------------------------------------ */

static uint64_t fold_byte(uint64_t hash, uint8_t value) {
    return (hash ^ value) * UINT64_C(1099511628211);
}

static uint64_t fold_u64(uint64_t hash, uint64_t value) {
    for (int j = 0; j < 8; j++) {
        hash = fold_byte(hash, (uint8_t)value);
        value >>= 8;
    }
    return hash;
}

static void fill_state(const ctx_t *c, uint64_t *st) {
    memset(st, 0, 32 * sizeof *st);
    st[0] = c->b;
    st[1] = c->occupied;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        st[2 + r] = c->R[r];
        st[6 + r] = c->sent[r];
        st[10 + r] = c->down[r];
        st[14 + r] = c->U[r];
    }
    st[18] = c->rx_data;
    st[19] = c->rx_ack;
    st[20] = c->tx_data;
    st[21] = c->tx_ack;
    st[22] = c->accepted;
    st[23] = c->dups;
    st[24] = c->blocked;
    st[25] = c->stale;
    st[26] = c->wire_bad;
    st[27] = c->ep_bad;
    st[28] = c->ack_ignored;
    st[29] = c->failed;
    st[30] = c->overwrites;
    st[31] = 0;
}

static uint64_t buffer_digest(const ctx_t *c) {
    uint64_t h = UINT64_C(14695981039346656037);
    for (uint64_t p = c->b; p < c->K && p - c->b < c->N; p++) {
        const slot_t *s = &c->slots[p % c->N];
        if (!s->in_use || s->psn != p) continue;
        h = fold_u64(h, p);
        h = fold_byte(h, s->mask);
        h = fold_byte(h, s->complete ? 1u : 0u);
        const uint8_t *pay = slot_payload(c, p);
        if (c->prim == P_ALLGATHER) {
            for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
                int present = (s->mask >> r) & 1;
                h = fold_byte(h, present ? 1u : 0u);
                if (present) {
                    const uint8_t *raw = pay + (size_t)r * c->pbytes;
                    for (uint32_t j = 0; j < c->pbytes; j++) h = fold_byte(h, raw[j]);
                }
            }
        } else if (c->prim == P_BCAST) {
            for (uint32_t j = 0; j < c->pbytes; j++) h = fold_byte(h, pay[j]);
        } else {
            for (uint32_t j = 0; j < c->D; j++) {
                uint32_t v;
                memcpy(&v, pay + 4u * j, 4);
                for (int k = 0; k < 4; k++) {
                    h = fold_byte(h, (uint8_t)v);
                    v >>= 8;
                }
            }
        }
    }
    return h;
}

static void push_snap(ctx_t *c, const uint8_t *tag, uint16_t taglen) {
    if (c->snap_n == c->snap_cap) {
        uint32_t cap = c->snap_cap ? c->snap_cap * 2u : 32u;
        snap_rec_t *grown = realloc(c->snaps, (size_t)cap * sizeof *grown);
        if (!grown) return;
        c->snaps = grown;
        c->snap_cap = cap;
    }
    snap_rec_t *s = &c->snaps[c->snap_n];
    fill_state(c, s->state);
    s->digest = buffer_digest(c);
    sha_finish(&c->sha, s->sha);
    s->packets = c->packets;
    s->bytes = c->bytes;
    s->taglen = taglen > MAX_TAG ? MAX_TAG : taglen;
    if (s->taglen) memcpy(s->tag, tag, s->taglen);
    c->snap_n++;
}

static void push_u8(uint8_t *buf, size_t *off, uint8_t v) { buf[(*off)++] = v; }

static void push_u16(uint8_t *buf, size_t *off, uint16_t v) {
    buf[(*off)++] = (uint8_t)v;
    buf[(*off)++] = (uint8_t)(v >> 8);
}

static void push_u32(uint8_t *buf, size_t *off, uint32_t v) {
    for (int i = 0; i < 4; i++) buf[(*off)++] = (uint8_t)(v >> (8 * i));
}

static void push_u64(uint8_t *buf, size_t *off, uint64_t v) {
    for (int i = 0; i < 8; i++) buf[(*off)++] = (uint8_t)(v >> (8 * i));
}

static size_t blob_size(const ctx_t *c) {
    size_t n = 256 + 8 + 32 + 16 + 4;
    for (uint32_t i = 0; i < c->trace_n; i++) n += 5 + c->trace_len[i];
    n += 4;
    for (uint32_t i = 0; i < c->snap_n; i++) n += 256 + 8 + 32 + 16 + 2 + c->snaps[i].taglen;
    return n;
}

static const uint8_t *build_blob(ctx_t *c) {
    if (c->blob) return c->blob;
    size_t size = blob_size(c);
    uint8_t *buf = malloc(size ? size : 1);
    if (!buf) return NULL;
    size_t off = 0;
    uint64_t st[32];
    fill_state(c, st);
    for (int i = 0; i < 32; i++) push_u64(buf, &off, st[i]);
    push_u64(buf, &off, buffer_digest(c));
    uint8_t sha[32];
    sha_finish(&c->sha, sha);
    for (int i = 0; i < 32; i++) push_u8(buf, &off, sha[i]);
    push_u64(buf, &off, c->packets);
    push_u64(buf, &off, c->bytes);
    push_u32(buf, &off, c->trace_n);
    for (uint32_t i = 0; i < c->trace_n; i++) {
        push_u8(buf, &off, (uint8_t)c->trace_rank[i]);
        push_u32(buf, &off, c->trace_len[i]);
        memcpy(buf + off, c->trace_frame[i], c->trace_len[i]);
        off += c->trace_len[i];
    }
    push_u32(buf, &off, c->snap_n);
    for (uint32_t i = 0; i < c->snap_n; i++) {
        const snap_rec_t *s = &c->snaps[i];
        for (int j = 0; j < 32; j++) push_u64(buf, &off, s->state[j]);
        push_u64(buf, &off, s->digest);
        for (int j = 0; j < 32; j++) push_u8(buf, &off, s->sha[j]);
        push_u64(buf, &off, s->packets);
        push_u64(buf, &off, s->bytes);
        push_u16(buf, &off, s->taglen);
        if (s->taglen) {
            memcpy(buf + off, s->tag, s->taglen);
            off += s->taglen;
        }
    }
    c->blob = buf;
    c->blob_len = off;
    return c->blob;
}

/* ------------------------------------------------------------------ */
/* program decoding                                                   */
/* ------------------------------------------------------------------ */

typedef struct {
    const uint8_t *buf;
    size_t len, off;
    int bad;
} reader_t;

static uint8_t rd_u8(reader_t *r) {
    if (r->off + 1 > r->len) { r->bad = 1; return 0; }
    return r->buf[r->off++];
}

static uint16_t rd_u16le(reader_t *r) {
    if (r->off + 2 > r->len) { r->bad = 1; return 0; }
    uint16_t v = (uint16_t)(r->buf[r->off] | ((uint16_t)r->buf[r->off + 1] << 8));
    r->off += 2;
    return v;
}

static uint32_t rd_u32le(reader_t *r) {
    if (r->off + 4 > r->len) { r->bad = 1; return 0; }
    uint32_t v = rd32le(r->buf + r->off);
    r->off += 4;
    return v;
}

static int64_t rd_i64le(reader_t *r) {
    uint64_t v = 0;
    for (int i = 0; i < 8; i++) v |= (uint64_t)rd_u8(r) << (8 * i);
    return (int64_t)v;
}

static const uint8_t *rd_bytes(reader_t *r, size_t n) {
    if (r->off + n > r->len) { r->bad = 1; return NULL; }
    const uint8_t *p = r->buf + r->off;
    r->off += n;
    return p;
}

static uint64_t train_ack_prefix(const ctx_t *c, int rank, uint64_t end) {
    switch (c->prim) {
    case P_ALLGATHER:
        return 3u * end;
    case P_RSCATTER: {
        int64_t v = (int64_t)end - (int64_t)rank * (int64_t)c->B;
        if (v < 0) v = 0;
        if ((uint64_t)v > c->B) v = c->B;
        return (uint64_t)v;
    }
    case P_REDUCE:
        return rank == c->root ? end : 0;
    case P_BCAST:
        return rank == c->root ? 0 : end;
    default:
        return end;
    }
}

static void run_train(ctx_t *c, uint32_t p0, uint32_t count, uint32_t width,
                      const uint8_t ranks[4], int reverse, uint32_t seed) {
    if (width == 0) return;
    uint64_t end_all = (uint64_t)p0 + count;
    for (uint64_t lo = p0; lo < end_all; lo += width) {
        uint64_t hi = lo + width;
        if (hi > end_all) hi = end_all;
        for (int i = 0; i < EPIC_STAR4_HOSTS; i++) {
            int rank = ranks[i];
            if (!is_required_source(c, rank)) continue;
            fill_payload(c, seed, 0, rank);  /* warm: overwritten per p below */
            for (uint64_t p = reverse ? hi - 1 : lo;
                 reverse ? p >= lo : p < hi;
                 reverse ? p-- : p++) {
                fill_payload(c, seed, p, rank);
                inject_data(c, rank, p, c->pbuf, NULL, 0);
            }
        }
        for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
            inject_ack(c, r, train_ack_prefix(c, r, hi));
        }
    }
}

int epic_case_run(void *context, const uint8_t *program, size_t length) {
    ctx_t *c = context;
    if (!c) return -1;
    reader_t r = { program, length, 0, 0 };
    while (r.off < r.len && !r.bad) {
        uint8_t op = rd_u8(&r);
        if (r.bad) break;
        switch (op) {
        case EV_DATA: {
            uint8_t rank = rd_u8(&r);
            uint32_t p = rd_u32le(&r);
            uint32_t count = rd_u32le(&r);
            int32_t step = (int32_t)rd_u32le(&r);
            uint32_t seed = rd_u32le(&r);
            uint32_t nvals = rd_u32le(&r);
            const uint8_t *vals = nvals ? rd_bytes(&r, (size_t)nvals * 4u) : NULL;
            uint32_t nxor = rd_u32le(&r);
            const uint8_t *xor = nxor ? rd_bytes(&r, (size_t)nxor * 5u) : NULL;
            if (r.bad || rank > 3) break;
            for (uint32_t i = 0; i < count; i++) {
                int64_t pi = (int64_t)p + (int64_t)i * (int64_t)step;
                if (pi < 0 || (uint64_t)pi >= (uint64_t)UINT64_C(0xffffffff)) continue;
                const uint8_t *payload;
                if (nvals && i == 0) {
                    /* host-order words -> network order on the wire */
                    for (uint32_t j = 0; j < c->D && j < nvals; j++) {
                        uint32_t v = rd32le(vals + 4u * j);
                        c->pbuf[4u * j] = (uint8_t)(v >> 24);
                        c->pbuf[4u * j + 1u] = (uint8_t)(v >> 16);
                        c->pbuf[4u * j + 2u] = (uint8_t)(v >> 8);
                        c->pbuf[4u * j + 3u] = (uint8_t)v;
                    }
                    payload = c->pbuf;
                } else {
                    fill_payload(c, seed, (uint64_t)pi, rank);
                    payload = c->pbuf;
                }
                inject_data(c, rank, (uint64_t)pi, payload, xor, nxor);
            }
            break;
        }
        case EV_ACK: {
            uint8_t rank = rd_u8(&r);
            uint32_t upto = rd_u32le(&r);
            if (r.bad || rank > 3) break;
            inject_ack(c, rank, upto);
            break;
        }
        case EV_WIRE: {
            uint8_t rank = rd_u8(&r);
            uint32_t n = rd_u32le(&r);
            const uint8_t *bytes = rd_bytes(&r, n);
            if (r.bad || rank > 3) break;
            ingress(c, rank, bytes, n);
            break;
        }
        case EV_BUDGET: {
            int64_t n = rd_i64le(&r);
            if (r.bad) break;
            c->budget = n;
            break;
        }
        case EV_FLUSH:
            service(c, -1);
            break;
        case EV_RETRY: {
            uint8_t rank = rd_u8(&r);
            if (r.bad || rank > 3) break;
            service(c, rank);
            break;
        }
        case EV_SNAP: {
            uint16_t n = rd_u16le(&r);
            const uint8_t *tag = rd_bytes(&r, n);
            if (r.bad) break;
            push_snap(c, tag, n);
            break;
        }
        case EV_TRAIN: {
            uint32_t p = rd_u32le(&r);
            uint32_t count = rd_u32le(&r);
            uint32_t width = rd_u32le(&r);
            uint8_t ranks[4];
            for (int i = 0; i < 4; i++) ranks[i] = rd_u8(&r);
            uint8_t reverse = rd_u8(&r);
            uint32_t seed = rd_u32le(&r);
            if (r.bad) break;
            run_train(c, p, count, width, ranks, reverse ? 1 : 0, seed);
            break;
        }
        default:
            r.bad = 1;
            break;
        }
    }
    return r.bad ? -1 : 0;
}

/* ------------------------------------------------------------------ */
/* lifecycle                                                          */
/* ------------------------------------------------------------------ */

void *epic_case_new(const epic_case_params_t *params) {
    if (!params) return NULL;
    ctx_t *c = calloc(1, sizeof *c);
    if (!c) return NULL;
    c->prim = params->primitive;
    c->mode = params->mode;
    c->root = params->root;
    c->K = params->segments;
    c->D = params->words;
    c->N = params->capacity;
    c->start = params->start & MASK24;
    c->trace_limit = params->trace > MAX_TRACE ? MAX_TRACE : params->trace;
    if (c->prim < 0 || c->prim > 5 || c->mode < 2 || c->mode > 3 ||
        c->root < 0 || c->root > 3 || c->K == 0 || c->N == 0) {
        free(c);
        return NULL;
    }
    if ((uint64_t)c->D * 4u > (uint64_t)EPIC_MAX_PAYLOAD_BYTES) {
        free(c);
        return NULL;
    }
    c->pbytes = c->D * 4u;
    c->required = (c->prim == P_BCAST) ? (uint8_t)(1u << c->root) : 0x0fu;
    c->B = (c->prim == P_RSCATTER) ? (c->K / 4u) : c->K;
    if (c->B == 0) c->B = 1;
    for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
        switch (c->prim) {
        case P_REDUCE:
            c->out_total[d] = (d == c->root) ? c->K : 0;
            break;
        case P_BCAST:
            c->out_total[d] = (d == c->root) ? 0 : c->K;
            break;
        case P_BARRIER:
            c->out_total[d] = 1;
            break;
        case P_ALLGATHER:
            c->out_total[d] = 3ull * c->K;
            break;
        case P_RSCATTER:
            c->out_total[d] = c->B;
            break;
        default:
            c->out_total[d] = c->K;
            break;
        }
    }
    c->slot_bytes = (c->prim == P_ALLGATHER) ? 4u * c->pbytes : c->pbytes;
    if (c->slot_bytes == 0) c->slot_bytes = 1;
    c->slots = calloc(c->N, sizeof *c->slots);
    c->pool = calloc(c->N, c->slot_bytes);
    if (!c->slots || !c->pool) {
        free(c->slots);
        free(c->pool);
        free(c);
        return NULL;
    }
    c->budget = -1;
    sha_init(&c->sha);
    return c;
}

const uint8_t *epic_case_result(void *context, size_t *length) {
    ctx_t *c = context;
    if (!c) return NULL;
    const uint8_t *blob = build_blob(c);
    if (length) *length = blob ? c->blob_len : 0;
    return blob;
}

void epic_case_free(void *context) {
    ctx_t *c = context;
    if (!c) return;
    free(c->snaps);
    free(c->slots);
    free(c->pool);
    free(c->blob);
    free(c);
}
