from wire import packet as build_packet  # noqa: E402

MASK = (1 << 24) - 1
PRIMS = {'allreduce': 0, 'reduce': 1, 'broadcast': 2, 'barrier': 3,
         'allgather': 4, 'reducescatter': 5}


def ipv4_csum_ok(hdr):
    total = 0
    for i in range(10):
        total += (hdr[2 * i] << 8) | hdr[2 * i + 1]
    while total >> 16:
        total = (total & 0xffff) + (total >> 16)
    return total == 0xffff


def icrc_ok(frame):
    iplen = (frame[16] << 8) | frame[17]
    if len(frame) != iplen + 14:
        return False
    body = bytearray(b'\xff' * 8 + frame[14:len(frame) - 4])
    body[9] = 255
    body[16] = 255
    body[18:20] = b'\xff\xff'
    body[34:36] = b'\xff\xff'
    body[40] = 255
    return zlib.crc32(bytes(body)) == struct.unpack('<I', frame[-4:])[0]


def parse_wire(frame, words):
    """Return None when wire-invalid, else ('data'|'ack', psn, qpn, payload)."""
    if len(frame) < 58:
        return None
    if frame[12:14] != b'\x08\x00':
        return None
    ip = frame[14:]
    if ip[0] != 0x45:
        return None
    iplen = (ip[2] << 8) | ip[3]
    if iplen + 14 != len(frame):
        return None
    if ip[9] != 17:
        return None
    frag = (ip[6] << 8) | ip[7]
    if frag not in (0x0000, 0x4000):
        return None
    if not ipv4_csum_ok(bytes(ip[:20])):
        return None
    udp = ip[20:]
    udplen = (udp[4] << 8) | udp[5]
    if udplen + 20 != iplen or udplen < 24:
        return None
    if ((udp[0] << 8) | udp[1]) != 4791 or ((udp[2] << 8) | udp[3]) != 4791:
        return None
    if (udp[6] << 8) | udp[7]:
        return None
    bth = udp[8:]
    opcode = bth[0]
    if opcode not in (0x04, 0x11):
        return None
    if bth[1] != 0:
        return None
    if ((bth[2] << 8) | bth[3]) != 0xffff:
        return None
    qpn = struct.unpack('!I', bytes(bth[4:8]))[0]
    if qpn & 0xff000000:
        return None
    apsn = struct.unpack('!I', bytes(bth[8:12]))[0]
    top = apsn >> 24
    if opcode == 0x04:
        if top != 0x80:
            return None
    elif top != 0x00:
        return None
    psn = apsn & MASK
    bodylen = udplen - 24
    if opcode == 0x11:
        if bodylen != 4:
            return None
        aeth = bth[12:16]
        if aeth[0] != 0x1f:
            return None
        low = (aeth[1] << 16) | (aeth[2] << 8) | aeth[3]
        if low != ((psn + 1) & MASK):
            return None
        if not icrc_ok(frame):
            return None
        return ('ack', psn, qpn, b'')
    if bodylen != 4 * words:
        return None
    if not icrc_ok(frame):
        return None
    return ('data', psn, qpn, bytes(bth[12:12 + bodylen]))


def ordinal_excluding(excluded, rank):
    order = [r for r in range(4) if r != excluded]
    return order.index(rank)


def rank_from_ordinal(excluded, ordinal):
    return [r for r in range(4) if r != excluded][ordinal]


class Model:
    def __init__(self, case):
        self.prim = case['primitive']
        self.mode = case['mode']
        self.root = case['root']
        self.K = case['segments']
        self.D = case['words']
        self.N = case['capacity']
        self.start = case['start']
        self.trace_limit = case.get('trace', 0)
        self.pbytes = 4 * self.D
        self.required = (1 << self.root) if self.prim == 'broadcast' else 0xF
        self.B = self.K // 4 if self.prim == 'reducescatter' else max(self.K, 1)
        self.b = 0
        self.slots = {}          # p -> dict(mask, raw{r:bytes}, acc[list])
        self.R = [0] * 4
        self.E = [0] * 4
        self.U = [0] * 4
        self.sent = [0] * 4
        self.down = [0] * 4
        self.repeat = [False] * 4
        self.budget = -1
        self.ctr = dict(rx_data=0, rx_ack=0, tx_data=0, tx_ack=0, accepted=0,
                        dups=0, blocked=0, stale=0, wire=0, ep=0, ignored=0,
                        failed=0, over=0)
        self.tape = hashlib.sha256()
        self.packets = 0
        self.bytes = 0
        self.trace = []
        self.snaps = []
        self.out_total = [0] * 4
        for d in range(4):
            if self.prim == 'reduce':
                self.out_total[d] = self.K if d == self.root else 0
            elif self.prim == 'broadcast':
                self.out_total[d] = 0 if d == self.root else self.K
            elif self.prim == 'barrier':
                self.out_total[d] = 1
            elif self.prim == 'allgather':
                self.out_total[d] = 3 * self.K
            elif self.prim == 'reducescatter':
                self.out_total[d] = self.B
            else:
                self.out_total[d] = self.K

    # ---------------- slots
    def slot(self, p):
        s = self.slots.get(p)
        if s is not None and p - self.b < self.N:
            return s
        return s

    def make_slot(self, p):
        s = self.slots.get(p)
        if s is None:
            s = {'mask': 0, 'raw': {}, 'acc': [0] * self.D, 'p': p}
            self.slots[p] = s
        return s

    def complete(self, s):
        return s is not None and s['mask'] == self.required

    # ---------------- sequence prefixes
    def advance_R(self, r):
        while self.R[r] < self.K:
            p = self.R[r]
            if p < self.b:
                self.R[r] = self.b
                continue
            s = self.slots.get(p)
            if s is not None and (s['mask'] >> r) & 1:
                self.R[r] += 1
            else:
                break

    def safe(self, r, p):
        if self.prim == 'allreduce':
            return self.down[r] > p
        if self.prim == 'barrier':
            return self.down[r] >= 1
        if self.prim == 'reduce':
            return self.down[self.root] > p
        if self.prim == 'broadcast':
            return all(self.down[d] > p for d in range(4) if d != self.root)
        if self.prim == 'reducescatter':
            d = p // self.B
            return self.down[d] > p % self.B
        if self.prim == 'allgather':
            for d in range(4):
                if d == r:
                    continue
                if self.down[d] < 3 * p + ordinal_excluding(d, r) + 1:
                    return False
            return True
        return False

    def advance_E(self):
        for r in range(4):
            if self.mode == 3:
                self.E[r] = self.R[r]
            else:
                while self.E[r] < self.R[r] and self.safe(r, self.E[r]):
                    self.E[r] += 1

    def outputs_acked(self, p):
        if self.prim == 'allreduce':
            return all(self.down[d] > p for d in range(4))
        if self.prim == 'reduce':
            return self.down[self.root] > p
        if self.prim == 'broadcast':
            return all(self.down[d] > p for d in range(4) if d != self.root)
        if self.prim == 'barrier':
            return all(self.down[d] >= 1 for d in range(4))
        if self.prim == 'allgather':
            return all(self.down[d] >= 3 * p + 3 for d in range(4))
        if self.prim == 'reducescatter':
            d = p // self.B
            return self.down[d] > p % self.B
        return False

    def required_sources(self):
        return [self.root] if self.prim == 'broadcast' else [0, 1, 2, 3]

    def retire(self):
        while self.b < self.K:
            p = self.b
            s = self.slots.get(p)
            if not self.complete(s):
                break
            if not self.outputs_acked(p):
                break
            if not all(self.U[r] > p for r in self.required_sources()):
                break
            del self.slots[p]
            self.b += 1

    # ---------------- output space
    def record_input(self, d, q):
        if self.prim == 'allgather':
            return q // 3
        if self.prim == 'reducescatter':
            return d * self.B + q
        if self.prim == 'barrier':
            return 0
        return q

    def record_ready(self, d, q):
        p = self.record_input(d, q)
        if p >= self.K:
            return False
        return self.complete(self.slots.get(p))

    def record_payload(self, d, q):
        p = self.record_input(d, q)
        s = self.slots.get(p)
        if self.prim == 'barrier':
            return b''
        if self.prim == 'allgather':
            src = rank_from_ordinal(d, q % 3)
            return s['raw'][src]
        if self.prim == 'broadcast':
            return s['raw'][self.root]
        return struct.pack('!%dI' % self.D, *[v & 0xffffffff for v in s['acc']])

    # ---------------- emission
    def transmit(self, rank, frame, is_ack):
        if self.budget == 0:
            self.ctr['failed'] += 1
            return False
        if self.budget > 0:
            self.budget -= 1
        self.tape.update(bytes([rank]) + struct.pack('<I', len(frame)) + frame)
        self.packets += 1
        self.bytes += len(frame)
        if is_ack:
            self.ctr['tx_ack'] += 1
        else:
            self.ctr['tx_data'] += 1
        if len(self.trace) < self.trace_limit:
            self.trace.append({'rank': rank, 'hex': frame.hex()})
        return True

    def emit_ack(self, r, prefix):
        psn = (self.start + prefix - 1) & MASK
        return self.transmit(r, build_packet(r, psn, ack=True, outgoing=True), True)

    def emit_record(self, d, q):
        psn = (self.start + q) & MASK
        return self.transmit(d, build_packet(d, psn, self.record_payload(d, q),
                                             outgoing=True), False)

    def service(self, retry_rank=None):
        self.advance_E()
        if retry_rank is not None:
            self.repeat[retry_rank] = True
        for r in range(4):
            if self.E[r] == 0:
                continue
            if self.E[r] <= self.U[r] and not self.repeat[r]:
                continue
            if not self.emit_ack(r, self.E[r]):
                self.retire()
                return
            self.U[r] = self.E[r]
            self.repeat[r] = False
        if retry_rank is not None:
            q = self.down[retry_rank]
            while q < self.sent[retry_rank]:
                if not self.emit_record(retry_rank, q):
                    self.retire()
                    return
                q += 1
        for d in range(4):
            while self.sent[d] < self.out_total[d] and self.record_ready(d, self.sent[d]):
                if not self.emit_record(d, self.sent[d]):
                    self.retire()
                    return
                self.sent[d] += 1
        self.retire()

    # ---------------- ingress
    def handle_data(self, rank, p, payload):
        if p >= self.b + self.N:
            self.ctr['blocked'] += 1
            return
        if p < self.b:
            self.ctr['stale'] += 1
            self.repeat[rank] = True
            return
        s = self.slots.get(p)
        if s is not None and (s['mask'] >> rank) & 1:
            self.ctr['dups'] += 1
            self.repeat[rank] = True
            return
        s = self.make_slot(p)
        if self.prim == 'allgather':
            s['raw'][rank] = payload
        elif self.prim == 'broadcast':
            s['raw'][rank] = payload
        elif self.prim != 'barrier':
            words = struct.unpack('!%dI' % self.D, payload) if self.D else ()
            for j, v in enumerate(words):
                s['acc'][j] = (s['acc'][j] + v) & 0xffffffff
        s['mask'] |= 1 << rank
        self.ctr['accepted'] += 1
        self.advance_R(rank)

    def handle_ack(self, rank, psn):
        length = (psn - self.start + 1) & MASK
        if length > self.down[rank] and length <= self.sent[rank]:
            self.down[rank] = length
        else:
            self.ctr['ignored'] += 1

    def ingress(self, rank, frame):
        parsed = parse_wire(frame, self.D)
        if parsed is None:
            self.ctr['wire'] += 1
            return
        kind, psn, qpn, payload = parsed
        hostmac = bytes((2, 0, 0, 0, 0, rank + 1))
        swmac = bytes((2, 1, 0, 0, 0, rank + 1))
        hostip = bytes((10, 0, 0, rank + 1))
        swip = bytes((10, 0, 0, 101 + rank))
        if frame[0:6] != swmac or frame[6:12] != hostmac:
            self.ctr['ep'] += 1
            return
        if frame[26:30] != hostip or frame[30:34] != swip:
            self.ctr['ep'] += 1
            return
        if qpn != 0x200 + rank:
            self.ctr['ep'] += 1
            return
        if kind == 'ack':
            self.ctr['rx_ack'] += 1
            self.handle_ack(rank, psn)
        else:
            p = (psn - self.start) & MASK
            if p >= self.K or (self.prim == 'broadcast' and rank != self.root):
                self.ctr['ep'] += 1
                return
            self.ctr['rx_data'] += 1
            self.handle_data(rank, p, payload)
        self.service()

    # ---------------- certificates
    def state(self):
        st = [0] * 32
        st[0] = self.b
        st[1] = sum(1 for p in self.slots if p >= self.b and p - self.b < self.N)
        for r in range(4):
            st[2 + r] = self.R[r]
            st[6 + r] = self.sent[r]
            st[10 + r] = self.down[r]
            st[14 + r] = self.U[r]
        order = ['rx_data', 'rx_ack', 'tx_data', 'tx_ack', 'accepted', 'dups',
                 'blocked', 'stale', 'wire', 'ep', 'ignored', 'failed', 'over']
        for i, key in enumerate(order):
            st[18 + i] = self.ctr[key]
        return st

    def digest(self):
        h = 14695981039346656037
        prime = 1099511628211
        m64 = (1 << 64) - 1

        def fold(data):
            nonlocal h
            for byte in data:
                h = ((h ^ byte) * prime) & m64

        for p in sorted(self.slots):
            if p < self.b or p - self.b >= self.N:
                continue
            s = self.slots[p]
            fold(struct.pack('<Q', p))
            fold(bytes([s['mask'], 1 if self.complete(s) else 0]))
            if self.prim == 'allgather':
                for r in range(4):
                    present = (s['mask'] >> r) & 1
                    fold(bytes([present]))
                    if present:
                        fold(s['raw'][r])
            elif self.prim == 'broadcast':
                fold(s['raw'][self.root])
            elif self.prim == 'barrier':
                pass
            else:
                fold(struct.pack('<%dI' % self.D, *[v & 0xffffffff for v in s['acc']]))
        return '%016x' % h

    def snapshot(self, tag=None):
        snap = {'state': self.state(), 'buffer': self.digest(),
                'wire_sha256': self.tape.hexdigest(), 'packets': self.packets,
                'bytes': self.bytes}
        if tag is not None:
            snap['tag'] = tag
        return snap

    def certificate(self):
        return {**self.snapshot(), 'snapshots': self.snaps, 'trace': self.trace}


def payload_words(seed, p, rank, words):
    return [(seed + 0x9e3779b9 * (p + 1) + 0x85ebca6b * (rank + 1) +
             0xc2b2ae35 * (j + 1)) & 0xffffffff for j in range(words)]


def run(case):
    """Replay a case with the reference model, mirroring wire.py expansion."""
    model = Model(case)
    base = case['start']
    kind = case['primitive']
    K = case['segments']
    D = case['words']
    for op in case['events']:
        name = op['op']
        if name == 'data':
            r = op['rank']
            count = op.get('count', 1)
            step = op.get('step', 1)
            seed = op.get('seed', 0)
            edits = op.get('xor', [])
            for i in range(count):
                p = op['p'] + i * step
                if 'values' in op:
                    body = struct.pack('!%dI' % len(op['values']), *op['values'])
                else:
                    body = struct.pack('!%dI' % D, *payload_words(seed, p, r, D))
                frame = bytearray(build_packet(r, (base + p) & MASK, body))
                for offset, value in edits:
                    frame[offset] ^= value
                model.ingress(r, bytes(frame))
        elif name == 'ack':
            model.ingress(op['rank'],
                          build_packet(op['rank'], (base + op['upto'] - 1) & MASK,
                                       ack=True))
        elif name == 'wire':
            model.ingress(op['rank'], bytes.fromhex(op['hex']))
        elif name == 'budget':
            model.budget = op['n']
        elif name == 'flush':
            model.service()
        elif name == 'retry':
            model.service(op['rank'])
        elif name == 'snap':
            model.snaps.append(model.snapshot(op['tag']))
        elif name == 'train':
            end = op['p'] + op['count']
            width = op['width']
            reverse = op.get('reverse', False)
            seed = op.get('seed', 0)
            for lo in range(op['p'], end, width):
                hi = min(end, lo + width)
                for r in op['ranks']:
                    if kind == 'broadcast' and r != case['root']:
                        continue
                    seq = range(hi - 1, lo - 1, -1) if reverse else range(lo, hi)
                    for p in seq:
                        body = struct.pack('!%dI' % D, *payload_words(seed, p, r, D))
                        model.ingress(r, build_packet(r, (base + p) & MASK, body))
                for r in range(4):
                    if kind == 'allgather':
                        n = 3 * hi
                    elif kind == 'reducescatter':
                        n = max(0, min(K // 4, hi - r * (K // 4)))
                    elif (kind != 'reduce' or r == case['root']) and \
                            (kind != 'broadcast' or r != case['root']):
                        n = hi
                    else:
                        n = 0
                    model.ingress(r, build_packet(r, (base + n - 1) & MASK, ack=True))
        else:
            raise ValueError('unknown op')
    return model.certificate()
