                                     struct.pack('!%dI' % D, *rand_words(rng, D)))
            if rng.random() < 0.55:
                frame = corrupt(rng, frame, D)
            events.append({'op': 'wire', 'rank': r, 'hex': frame.hex()})
        elif pick < 0.72:
            events.append({'op': 'budget', 'n': rng.choice([-1, 0, 1, 2, 3, 7, 1 << 20])})
        elif pick < 0.78:
            events.append({'op': 'flush'})
        elif pick < 0.86:
            events.append({'op': 'retry', 'rank': rng.randrange(4)})
        elif pick < 0.92:
            events.append({'op': 'snap', 'tag': rng.choice(['', 'a', 'x' * 64, 'tagé'])})
        else:
            p = rng.randrange(K)
            count = rng.randrange(1, min(9, K - p + 1))
            events.append({'op': 'train', 'p': p, 'count': count,
                           'width': rng.randrange(1, N + 1),
                           'ranks': rng.sample([0, 1, 2, 3], 4),
                           'reverse': rng.random() < 0.5,
                           'seed': rng.randrange(1 << 32)})
    return {'primitive': prim, 'mode': mode, 'root': root, 'segments': K,
            'words': D, 'capacity': N, 'start': start, 'events': events,
            'trace': rng.choice([0, 0, 3, 32])}


def equal(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(equal(x, y) for x, y in zip(a, b))
    return a == b


def diff(path, got, want, out):
    if isinstance(want, dict):
        for k in want:
            diff(path + '.' + str(k), got.get(k) if isinstance(got, dict) else None, want[k], out)
    elif isinstance(want, list):
        if not isinstance(got, list) or len(got) != len(want):
            out.append((path + '.len', got if not isinstance(got, list) else len(got), len(want)))
            return
        for i, (g, w) in enumerate(zip(got, want)):
            diff('%s[%d]' % (path, i), g, w, out)
    else:
        if got != want:
            out.append((path, got, want))


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    bad = 0
    for it in range(rounds):
        cases = [gen_case(rng) for _ in range(rng.randrange(1, 4))]
        want = [ref.run(c) for c in cases]
        got = solver.solve({'cases': cases})['cases']
        for i, (g, w) in enumerate(zip(got, want)):
            out = []
            diff('case%d' % i, g, w, out)
            if out:
                bad += 1
                print('=== MISMATCH seed=%d iter=%d case=%d' % (seed, it, i))
                print(json.dumps(cases[i])[:3000])
                for path, gv, wv in out[:12]:
                    print('  ', path, 'got=', str(gv)[:200], 'want=', str(wv)[:200])
                if bad > 3:
                    return 1
    print('done rounds=%d mismatches=%d' % (rounds, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    raise SystemExit(main())
