                json.dump(cases[i], open('/workspace/tmp/wbad_%d_%d.json' % (seed, it), 'w'), indent=1)
                if bad > 3:
                    return 1
    print('done wirefuzz seed=%d iters=%d bad=%d' % (seed, it + 1, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    raise SystemExit(main())
