/* ------------------------------------------------------------------ */
/* service opportunity                                                */
/* ------------------------------------------------------------------ */

static void service(ctx_t *c, int retry_rank) {
    advance_eligible(c);
    if (retry_rank >= 0) c->repeat[retry_rank] = 1;

    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (c->E[r] == 0) continue;
        if (c->E[r] <= c->U[r] && !c->repeat[r]) continue;
        if (!emit_ack(c, r, c->E[r])) goto done;
        c->U[r] = c->E[r];
        c->repeat[r] = 0;
    }

    if (retry_rank >= 0) {
        uint64_t q = c->down[retry_rank];
        while (q < c->sent[retry_rank]) {
            if (!emit_record(c, retry_rank, q)) goto done;
            q++;
        }
    }

    for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
        while (c->sent[d] < c->out_total[d] && record_ready(c, d, c->sent[d])) {
            if (!emit_record(c, d, c->sent[d])) goto done;
            c->sent[d]++;
        }
    }

done:
    retire(c);
}

/* ------------------------------------------------------------------ */
/* ingress handling                                                   */
/* ------------------------------------------------------------------ */

static void store_contribution(ctx_t *c, uint64_t p, int rank,
                               const uint8_t *payload) {
    uint8_t *pay = slot_payload(c, p);
    switch (c->prim) {
    case P_ALLGATHER:
        memcpy(pay + (size_t)rank * c->pbytes, payload, c->pbytes);
        break;
    case P_BCAST:
        memcpy(pay, payload, c->pbytes);
        break;
    case P_BARRIER:
        break;
    default: {
        uint32_t *acc = (uint32_t *)pay;
        for (uint32_t j = 0; j < c->D; j++) acc[j] += rd32(payload + 4u * j);
        break;
    }
    }
}

static void handle_data(ctx_t *c, int rank, uint32_t p, const uint8_t *payload) {
    if ((uint64_t)p >= c->b + c->N) {
        c->blocked++;
        return;
    }
    if ((uint64_t)p < c->b) {
        c->stale++;
        c->repeat[rank] = 1;
        return;
    }
    slot_t *s = &c->slots[p % c->N];
    uint8_t bit = (uint8_t)(1u << rank);
    if (s->in_use && s->psn == p && (s->mask & bit)) {
        c->dups++;
        c->repeat[rank] = 1;
        return;
    }
    if (!s->in_use || s->psn != p) {
        if (s->in_use && s->psn != p) c->overwrites++;
        s->in_use = 1;
        s->psn = p;
        s->mask = 0;
        s->complete = 0;
        memset(slot_payload(c, p), 0, c->slot_bytes);
        c->occupied++;
    }
    store_contribution(c, p, rank, payload);
    s->mask |= bit;
    if (s->mask == c->required) s->complete = 1;
    c->accepted++;
    advance_received(c, rank);
}

static void handle_ack(ctx_t *c, int rank, uint32_t wire_psn) {
    uint32_t len = (wire_psn - c->start + 1u) & MASK24;
    if ((uint64_t)len > c->down[rank] && (uint64_t)len <= c->sent[rank]) {
        c->down[rank] = len;
    } else {
        c->ack_ignored++;
    }
}

static void ingress(ctx_t *c, int rank, const uint8_t *frame, size_t len) {
    frame_t fr;
    if (!wire_valid(frame, len, &fr)) {
        c->wire_bad++;
        return;
    }
    if (!fr.is_ack && fr.plen != c->pbytes) {
        c->wire_bad++;
        return;
    }
    if (!endpoint_valid(c, rank, frame, &fr)) {
        c->ep_bad++;
        return;
    }
    if (fr.is_ack) {
        c->rx_ack++;
        handle_ack(c, rank, fr.psn);
    } else {
        uint32_t p = (fr.psn - c->start) & MASK24;
        if (p >= c->K || !is_required_source(c, rank)) {
            c->ep_bad++;
            return;
        }
        c->rx_data++;
        handle_data(c, rank, p, fr.payload);
    }
    service(c, -1);
}

/* ------------------------------------------------------------------ */
/* ingress frame generation (event expansion)                         */
/* ------------------------------------------------------------------ */

static size_t build_ingress_data(ctx_t *c, int rank, uint32_t psn,
                                 const uint8_t *payload) {
    uint8_t hm[6], sm[6];
    port_macs(rank, hm, sm);

/* ------------------------------------------------------------------ */
/* egress                                                             */
/* ------------------------------------------------------------------ */

static int transmit(ctx_t *c, int rank, const uint8_t *frame, size_t len,
                    int is_ack) {
    if (c->budget == 0) {
        c->failed++;
        return 0;
    }
    if (c->budget > 0) c->budget--;
    uint8_t prefix[5];
    prefix[0] = (uint8_t)rank;
    prefix[1] = (uint8_t)(len & 0xffu);
    prefix[2] = (uint8_t)((len >> 8) & 0xffu);
    prefix[3] = (uint8_t)((len >> 16) & 0xffu);
    prefix[4] = (uint8_t)((len >> 24) & 0xffu);
    sha_update(&c->sha, prefix, sizeof prefix);
    sha_update(&c->sha, frame, len);
    c->packets++;
    c->bytes += len;
    if (is_ack) c->tx_ack++; else c->tx_data++;
    if (c->trace_n < c->trace_limit && c->trace_n < MAX_TRACE) {
        c->trace_rank[c->trace_n] = rank;
        c->trace_len[c->trace_n] = (uint32_t)len;
        memcpy(c->trace_frame[c->trace_n], frame, len);
        c->trace_n++;
    }
    return 1;
}

static int emit_ack(ctx_t *c, int rank, uint64_t prefix_len) {
    uint8_t hm[6], sm[6];
    uint32_t psn = (c->start + (uint32_t)((prefix_len - 1u) & MASK24)) & MASK24;
    port_macs(rank, hm, sm);
    size_t len = epic_build_roce_ack(c->fbuf, sizeof c->fbuf, sm, hm,
                                     switch_ip_of(rank), host_ip_of(rank),
                                     UDP_PORT_ROCE, UDP_PORT_ROCE,
                                     host_qpn_of(rank), psn);
    if (!len) return 0;
    return transmit(c, rank, c->fbuf, len, 1);
}

static int emit_data(ctx_t *c, int rank, uint64_t q, const uint8_t *raw,
                     const uint32_t *words) {
    uint8_t hm[6], sm[6];
    uint32_t psn = (uint32_t)((c->start + q) & MASK24);
    port_macs(rank, hm, sm);
    size_t len;
    if (raw) {
        len = epic_build_roce_data_raw(c->fbuf, sizeof c->fbuf, sm, hm,
                                       switch_ip_of(rank), host_ip_of(rank),
                                       UDP_PORT_ROCE, UDP_PORT_ROCE,
                                       host_qpn_of(rank), psn, raw, c->pbytes);
    } else {
        len = epic_build_roce_data(c->fbuf, sizeof c->fbuf, sm, hm,
                                   switch_ip_of(rank), host_ip_of(rank),
                                   UDP_PORT_ROCE, UDP_PORT_ROCE,
                                   host_qpn_of(rank), psn,
                                   (const int32_t *)words, c->pbytes);
    }
    if (!len) return 0;
    return transmit(c, rank, c->fbuf, len, 0);
}

/* ------------------------------------------------------------------ */
/* output space mapping                                               */
/* ------------------------------------------------------------------ */

static uint64_t record_input(const ctx_t *c, int dest, uint64_t q) {
    switch (c->prim) {
    case P_ALLGATHER:
        return q / 3u;
    case P_RSCATTER:
        return (uint64_t)dest * c->B + q;
    case P_BARRIER:
        return 0;
    default:
        return q;
    }
}

static int record_ready(const ctx_t *c, int dest, uint64_t q) {
    uint64_t p = record_input(c, dest, q);
    if (p >= c->K) return 0;
    const slot_t *s = &c->slots[p % c->N];
    return s->in_use && s->psn == p && s->complete;
}

static int emit_record(ctx_t *c, int dest, uint64_t q) {
    uint64_t p = record_input(c, dest, q);
    if (c->prim == P_BARRIER) return emit_data(c, dest, q, NULL, NULL);
    if (c->prim == P_ALLGATHER) {
        int ordinal = (int)(q % 3u);
        int src = rank_from_ordinal_excluding(dest, ordinal);
        return emit_data(c, dest, q, slot_payload(c, p) + (size_t)src * c->pbytes,
                         NULL);
    }
    if (c->prim == P_BCAST) return emit_data(c, dest, q, slot_payload(c, p), NULL);
    return emit_data(c, dest, q, NULL, slot_words(c, p));
}

/* ------------------------------------------------------------------ */
/* strict wire acceptance                                             */
/* ------------------------------------------------------------------ */

typedef struct {
    int is_ack;
    uint32_t psn;
    uint32_t qpn;
    const uint8_t *payload;
    uint32_t plen;
} frame_t;

static int wire_valid(const uint8_t *f, size_t len, frame_t *out) {
    const size_t head = sizeof(epic_eth_t) + sizeof(epic_ipv4_t) +
                        sizeof(epic_udp_t) + sizeof(epic_bth_t) + 4u;
    if (!f || len < head) return 0;
    if (rd16(f + 12) != 0x0800u) return 0;              /* Ethernet IPv4 */
    const uint8_t *ip = f + sizeof(epic_eth_t);
    if (ip[0] != 0x45) return 0;                        /* version/IHL */
    uint32_t iplen = rd16(ip + 2);
    if ((size_t)iplen + sizeof(epic_eth_t) != len) return 0;
    if (ip[9] != 17) return 0;                          /* protocol UDP */
    uint16_t frag = rd16(ip + 6);
    if (frag != 0x0000u && frag != 0x4000u) return 0;   /* DF only */
    if (!ip_checksum_ok(ip)) return 0;
    const uint8_t *udp = ip + sizeof(epic_ipv4_t);
    uint32_t udplen = rd16(udp + 4);
    if (udplen + sizeof(epic_ipv4_t) != iplen) return 0;
    if (udplen < sizeof(epic_udp_t) + sizeof(epic_bth_t) + 4u) return 0;
    if (rd16(udp) != UDP_PORT_ROCE) return 0;
    if (rd16(udp + 2) != UDP_PORT_ROCE) return 0;
    if (rd16(udp + 6) != 0) return 0;                   /* UDP checksum zero */
    const uint8_t *bth = udp + sizeof(epic_udp_t);
    uint8_t opcode = bth[0];
    if (opcode != 0x04 && opcode != 0x11) return 0;
    if (bth[1] != 0) return 0;                          /* flags/padding */
    if (rd16(bth + 2) != 0xffffu) return 0;             /* pkey */
    uint32_t qpn = rd32(bth + 4);
    if (qpn & 0xff000000u) return 0;                    /* QPN top byte */
    uint32_t apsn = rd32(bth + 8);
    uint8_t top = (uint8_t)(apsn >> 24);
    if (opcode == 0x04 ? (top != 0x80u) : (top != 0x00u)) return 0;
    uint32_t bodylen = udplen - (uint32_t)sizeof(epic_udp_t) -
                       (uint32_t)sizeof(epic_bth_t) - 4u;
    memset(out, 0, sizeof *out);
    out->psn = apsn & MASK24;
    out->qpn = qpn;
    if (opcode == 0x11) {
        if (bodylen != 4u) return 0;
        const uint8_t *aeth = bth + sizeof(epic_bth_t);
        if (aeth[0] != 0x1fu) return 0;
        uint32_t low = ((uint32_t)aeth[1] << 16) | ((uint32_t)aeth[2] << 8) |
                       (uint32_t)aeth[3];
        if (low != ((out->psn + 1u) & MASK24)) return 0;
        out->is_ack = 1;
    } else {
        out->is_ack = 0;
        out->payload = bth + sizeof(epic_bth_t);
        out->plen = bodylen;
    }
    uint32_t stored = rd32le(f + len - 4);
    if (epic_compute_icrc(f, len) != stored) return 0;
    return 1;
}

static int endpoint_valid(const ctx_t *c, int rank, const uint8_t *f,
                          const frame_t *fr) {
    uint8_t hm[6], sm[6];
    (void)c;
    port_macs(rank, hm, sm);
    if (memcmp(f, sm, 6) != 0) return 0;      /* destination = switch */
    if (memcmp(f + 6, hm, 6) != 0) return 0;  /* source = host */
    const uint8_t *ip = f + sizeof(epic_eth_t);
    const uint8_t *hi = (const uint8_t *)&(uint32_t){ host_ip_of(rank) };
    const uint8_t *si = (const uint8_t *)&(uint32_t){ switch_ip_of(rank) };
    if (memcmp(ip + 12, hi, 4) != 0) return 0;
    if (memcmp(ip + 16, si, 4) != 0) return 0;
    if (fr->qpn != switch_qpn_of(rank)) return 0;
    return 1;
